			Provider:      "skipped",
			RepoKey:       storage.Key,
			Commit:        head,
			Tree:          tree,
			Warnings:      []semanticWarning{{Code: "provider_skipped", Severity: "warning", Effect: "semantic facts unavailable", Detail: "semantic provider was skipped"}},
		}
		headerLine, err := json.Marshal(header)
		if err != nil {
